package bottlesong

import "fmt"

// numberWords maps a bottle count to the word used in the lyrics.
// The first word of a line is capitalized; "no" is lowercase because it
// appears mid-sentence ("There'll be no green bottles...").
var numberWords = map[int]string{
	0:  "no",
	1:  "One",
	2:  "Two",
	3:  "Three",
	4:  "Four",
	5:  "Five",
	6:  "Six",
	7:  "Seven",
	8:  "Eight",
	9:  "Nine",
	10: "Ten",
}

func Recite(startBottles, takeDown int) []string {
	var lines []string
	for bottles := startBottles; bottles > startBottles-takeDown; bottles-- {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		lines = append(lines,
			fmt.Sprintf("%s green %s hanging on the wall,", numberWords[bottles], bottleWord(bottles)),
			fmt.Sprintf("%s green %s hanging on the wall,", numberWords[bottles], bottleWord(bottles)),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green %s hanging on the wall.", numberWords[bottles-1], bottleWord(bottles-1)),
		)
	}
	return lines
}

func bottleWord(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

