import (
	"fmt"
	"strings"
	"unicode"
)

// numberWords maps a bottle count to the word used in the lyrics.
// Zero is "no", as in "There'll be no green bottles hanging on the wall."
var numberWords = map[int]string{
	0:  "no",
	1:  "one",
	2:  "two",
	3:  "three",
	4:  "four",
	5:  "five",
	6:  "six",
	7:  "seven",
	8:  "eight",
	9:  "nine",
	10: "ten",
}

func Recite(startBottles, takeDown int) []string {
	var lines []string
	for bottles := startBottles; bottles > startBottles-takeDown; bottles-- {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		lines = append(lines,
			fmt.Sprintf("%s green %s hanging on the wall,", title(numberWords[bottles]), bottleWord(bottles)),
			fmt.Sprintf("%s green %s hanging on the wall,", title(numberWords[bottles]), bottleWord(bottles)),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green %s hanging on the wall.", numberWords[bottles-1], bottleWord(bottles-1)),
		)
	}
	return lines
}

func bottleWord(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

// title uppercases the first rune of s, leaving the rest unchanged.
func title(s string) string {
	for i, r := range s {
		return string(unicode.ToUpper(r)) + s[i+len(string(r)):]
	}
	return s
}

var _ = strings.ToUpper // keep import if unused? no — see below

